t.script:
(function(){
  var f = document.querySelector('form[action$="/verificar"]');
  if(!f){ return; }

  var qtyInput  = document.getElementById('qty_input');
  var qtyVerify = document.getElementById('qty_hidden_verify');
  var btnVerify = document.getElementById('btn_verify');
  var buyForm   = document.getElementById('buyForm');
  var undo      = document.getElementById('sv_undo');
  var availEl   = document.getElementById('available_qty');
  var available = availEl ? (parseFloat(availEl.dataset.available || '0') || 0) : 0;
  var msgEl     = document.getElementById('svMsg');
  var msgTimer  = null;

  function qty(){
    return qtyInput ? (parseFloat(qtyInput.value || '0') || 0) : 0;
  }

  // Mensaje en pantalla (reemplaza a los alert()).
  function mostrarMensaje(texto){
    if(!msgEl){ return; }
    msgEl.textContent = texto;
    msgEl.style.display = 'block';
    msgEl.scrollIntoView({behavior:'smooth', block:'center'});
    if(msgTimer){ clearTimeout(msgTimer); }
    msgTimer = setTimeout(function(){ msgEl.style.display = 'none'; }, 6000);
  }
  function limpiarMensaje(){ if(msgEl){ msgEl.style.display = 'none'; } }

  // La cantidad se lee del campo visible, no de los ocultos: asi el
  // envio a verificacion no depende de otros scripts de la pagina.
  f.addEventListener('submit', function(ev){
    var q = qty();
    if(q <= 0 || q > available){
      ev.preventDefault();
      mostrarMensaje('Ingresa una cantidad válida (entre 1 y ' + available + ') antes de enviar a verificación.');
      return;
    }
    if(qtyVerify){ qtyVerify.value = q; }
  });

  // ---- Desglose de valores antes de confirmar ----
  var modal   = document.getElementById('svModal');
  var precioEl= document.getElementById('unit_price');
  var precio  = precioEl ? (parseFloat(precioEl.dataset.price || '0') || 0) : 0;
  var cfgEl   = document.getElementById('svFeeCfg');
  var cfg = cfgEl ? {
    base:  parseFloat(cfgEl.dataset.base  || '0') || 0,
    cents: parseFloat(cfgEl.dataset.cents || '0') || 0,
    min:   parseFloat(cfgEl.dataset.min   || '0') || 0,
    max:   parseFloat(cfgEl.dataset.max   || '0') || 0
  } : {base:0, cents:0, min:0, max:0};

  // Mismo cálculo que en el servidor: base + variable, acotado.
  function honorarioDe(q){
    var bruto = cfg.base + (q * cfg.cents / 100);
    var val = bruto;
    if(cfg.min){ val = Math.max(val, cfg.min); }
    if(cfg.max){ val = Math.min(val, cfg.max); }
    return { total: val, bruto: bruto };
  }

  function dinero(n){ return (isNaN(n) ? 0 : n).toFixed(2); }

  function abrirDesglose(){
    var q = qty();
    var elegido = f.querySelector('input[name="verifier_ref"]:checked');
    if(q <= 0 || q > available){
      mostrarMensaje('Ingresa una cantidad válida (entre 1 y ' + available + ') antes de continuar.');
      return;
    }
    if(!elegido){
      mostrarMensaje('Elige un verificador antes de continuar.');
      return;
    }
    limpiarMensaje();
    var nombre = elegido.closest('label')
                        .querySelector('.sv-verifier-name');
    var hon = honorarioDe(q);
    document.getElementById('svQty').textContent = q;
    document.getElementById('svProd').textContent = dinero(q * precio);
    document.getElementById('svFee').textContent = dinero(hon.total);
    document.getElementById('svTotal').textContent = dinero(q * precio + hon.total);

    // Se explica de dónde sale el importe, en vez de soltar un número.
    var detalle = '$' + dinero(cfg.base) + ' base + ' +
                  cfg.cents + '\u00A2 x ' + q;
    if(hon.total < hon.bruto){ detalle += ' (tope $' + dinero(cfg.max) + ')'; }
    if(hon.total > hon.bruto){ detalle += ' (mínimo $' + dinero(cfg.min) + ')'; }
    document.getElementById('svFeeDetail').textContent = detalle;
    document.getElementById('svVerif').textContent =
      nombre ? nombre.textContent.trim() : '—';
    if(modal){ modal.style.display = 'flex'; }
  }

  if(btnVerify){ btnVerify.addEventListener('click', abrirDesglose); }
  var cancelar = document.getElementById('svCancel');
  if(cancelar){
    cancelar.addEventListener('click', function(){
      if(modal){ modal.style.display = 'none'; }
    });
  }
  var confirmar = document.getElementById('svConfirm');
  if(confirmar){
    confirmar.addEventListener('click', function(){
      // Copiamos la cantidad al campo oculto: f.submit() NO dispara
      // el listener 'submit', así que hay que fijarla aquí a mano.
      if(qtyVerify){ qtyVerify.value = qty(); }
      confirmar.setAttribute('disabled', 'disabled');
      if(modal){ modal.style.display = 'none'; }
      // Simulador de pago (demo): 5 s antes de enviar a verificación.
      var overlay = document.getElementById('payOverlay');
      var countEl = document.getElementById('payCount');
      if(overlay){ overlay.style.display = 'flex'; }
      var left = 5;
      if(countEl){ countEl.textContent = left; }
      var timer = setInterval(function(){
        left -= 1;
        if(countEl){ countEl.textContent = left; }
        if(left <= 0){
          clearInterval(timer);
          f.submit();
        }
      }, 1000);
    });
  }

  function sync(){
    var elegido = f.querySelector('input[name="verifier_ref"]:checked');

    // Respaldo de :has(): marcar la tarjeta elegida por clase.
    f.querySelectorAll('label.sv-verifier').forEach(function(el){
      var r = el.querySelector('input[name="verifier_ref"]');
      el.classList.toggle('is-selected', !!(r && r.checked));
    });
    var q = qty();
    var valido = q > 0 && q <= available;

    // Con verificador elegido la compra directa deja de aplicar.
    if(buyForm){ buyForm.style.display = elegido ? 'none' : ''; }
    if(undo){ undo.style.display = elegido ? '' : 'none'; }
    if(btnVerify){
      if(valido){ btnVerify.removeAttribute('disabled'); }
      else { btnVerify.setAttribute('disabled', 'disabled'); }
    }
  }

  f.querySelectorAll('input[name="verifier_ref"]').forEach(function(r){
    r.addEventListener('change', sync);
  });
  if(qtyInput){ qtyInput.addEventListener('input', sync); }

  // ---- Buscador y recorte de la lista de verificadoras ----
  // Vienen todas en la página, así que el filtro es instantáneo.
  var VISIBLES = 3;
  var buscador = document.getElementById('sv_buscar_verif');
  var verTodas = document.getElementById('sv_ver_todas');
  var restantes = document.getElementById('sv_restantes');
  var sinResultados = document.getElementById('sv_sin_resultados');
  var fichas = Array.prototype.slice.call(
    f.querySelectorAll('label.sv-verifier'));
  var expandido = false;

  function pintarLista() {
    var texto = (buscador ? buscador.value : '').trim().toLowerCase();
    var coinciden = fichas.filter(function (el) {
      return !texto || (el.dataset.buscar || '').indexOf(texto) !== -1;
    });

    // Buscando se muestran todas las coincidencias; sin buscar,
    // solo las primeras (que son las mejor calificadas).
    var tope = (texto || expandido) ? coinciden.length : VISIBLES;

    fichas.forEach(function (el) {
      var pos = coinciden.indexOf(el);
      var marcado = el.querySelector('input[name="verifier_ref"]:checked');
      // La elegida no se oculta nunca: si desapareciera, el
      // comprador enviaría el formulario sin saber a quién eligió.
      el.style.display = (marcado || (pos !== -1 && pos < tope)) ? '' : 'none';
    });

    if (sinResultados) {
      sinResultados.style.display = coinciden.length ? 'none' : '';
    }
    var ocultas = Math.max(0, coinciden.length - tope);
    if (verTodas) {
      verTodas.style.display = ocultas > 0 ? '' : 'none';
      if (restantes) { restantes.textContent = ocultas; }
    }
  }

  if (buscador) { buscador.addEventListener('input', pintarLista); }
  if (verTodas) {
    verTodas.addEventListener('click', function (ev) {
      ev.preventDefault();
      expandido = true;
      pintarLista();
    });
  }
  fichas.forEach(function (el) {
    el.addEventListener('change', pintarLista);
  });
  pintarLista();
  if(undo){
    undo.addEventListener('click', function(ev){
      ev.preventDefault();
      var c = f.querySelector('input[name="verifier_ref"]:checked');
      if(c){ c.checked = false; }
      sync();
    });
  }
  sync();
})();

(function(){
  // Los avisos de "pendiente de verificación" son informativos y el
  // estado sigue visible en cada compra, así que se desvanecen solos.
  // Los de "ya puedes concluir" no: ahí hay una acción por hacer.
  var autos = document.querySelectorAll('.sv-alert--auto');
  if(!autos.length){ return; }
  setTimeout(function(){
    autos.forEach(function(el){
      el.classList.add('sv-alert--fading');
      setTimeout(function(){ el.style.display = 'none'; }, 600);
    });
  }, 7000);
})();

(function(){
  // Los avisos de "pendiente de verificación" son informativos y el
  // estado sigue visible en cada compra, así que se desvanecen solos.
  // Los de "ya puedes concluir" no: ahí hay una acción por hacer.
  var autos = document.querySelectorAll('.sv-alert--auto');
  if(!autos.length){ return; }
  setTimeout(function(){
    autos.forEach(function(el){
      el.classList.add('sv-alert--fading');
      setTimeout(function(){ el.style.display = 'none'; }, 600);
    });
  }, 7000);
})();
